import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';class SettingsCubit extends Cubit<SettingsState> {  SettingsCubit() : super(SettingsState());  void toggleTheme() {    emit(state.copyWith(      themeMode: state.themeMode == ThemeMode.light ? ThemeMode.dark : ThemeMode.light,    ));  }  void changeLanguage(Locale locale) {    emit(state.copyWith(locale: locale));  }}class SettingsState {  final ThemeMode themeMode;  final Locale locale;  SettingsState({    this.themeMode = ThemeMode.light,    this.locale = const Locale('ar'),  });  SettingsState copyWith({    ThemeMode? themeMode,    Locale? locale,  }) {    return SettingsState(      themeMode: themeMode ?? this.themeMode,      locale: locale ?? this.locale,    );  }}